            try:
                a = env.execute(probe, max_rows=1)
                b = env.execute(probe_d, max_rows=1)
                if a.get("ok") and b.get("ok") and a.get("rows") and b.get("rows"):
                    na, nb = a["rows"][0][0], b["rows"][0][0]
                    if isinstance(na, int) and isinstance(nb, int) and na > nb:
                        notes.append(
                            "Your query returns %d rows but only %d distinct rows: the join "
                            "fans out and repeats the same entity. The question asks for a list "
                            "of entities, so each should appear once — add DISTINCT (or replace "
                            "the join with an EXISTS/IN filter). Keep duplicates only if you "
                            "intend to return the full joined records via `SELECT *`." % (na, nb)
                        )
            except Exception:
                pass
    return notes


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 800)
    schema = env.schema(task["db_id"])
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""

    user = "Database: %s\n\nSchema:\n%s\n" % (task["db_id"], schema)
    if desc.strip():
        user += "\nColumn descriptions:\n%s\n" % desc.strip()[:2500]
    user += "\nQuestion: %s" % task["question"]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]
    user += "\n\nWrite the query now."

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": sql}

    # Cheap self-check: spend the second call only when something looks wrong.
    try:
        res = env.execute(sql, max_rows=20)
    except Exception:
        res = {"ok": False, "error": "execution failed", "rows": [], "n_rows": 0}

    ok = bool(res.get("ok"))
    nrows = res.get("n_rows", len(res.get("rows") or []))
    hard_fail = (not ok) or nrows == 0

    shape_notes = []
    if ok and nrows > 0:
        try:
            shape_notes = _shape_feedback(env, task, sql, res)
        except Exception:
            shape_notes = []

    if not hard_fail and not shape_notes:
        return {"sql": sql}

    fb = ["Your draft query was:", "```sql", sql, "```"]
    if not ok:
        fb.append("It failed to execute. Error: %s" % str(res.get("error"))[:400])
    elif nrows == 0:
        fb.append(
            "It executed but returned ZERO rows. That usually means a literal value does not "
            "match what is stored (spacing/casing/wording), a join key is wrong, or a NOT IN "
            "subquery contains NULLs. Re-read the question: an empty answer is rarely intended."
        )
    else:
        fb.append(
            "It executed and returned %d row(s) with columns: %s."
            % (nrows, ", ".join(map(str, res.get("columns") or []))[:300])
        )
        for note in shape_notes:
            fb.append("Shape issue: " + note)
    samples = ""
    if hard_fail:
        try:
            samples = _sample_values(env, schema, sql)
        except Exception:
            samples = ""
    if samples:
        fb.append("Actual stored values in the database:\n" + samples)
    fb.append(
        "Return a corrected query in a single ```sql block. Fix only the flagged problem: "
        "loosen string matching (LIKE '%keyword%' / lower(...)) when the exact value is unknown, "
        "use EXCEPT or NOT EXISTS for negation, choose `SELECT *` for vague entity/detail "
        "questions and exactly the named attributes otherwise, and remove join fan-out "
        "duplicates with DISTINCT when a list of entities is requested."
    )

    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": "\n".join(fb)},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=5)
    except Exception:
        res2 = {"ok": False}
    if res2.get("ok"):
        return {"sql": sql2}
    return {"sql": sql if ok else sql2}
